"""Basic structural checks for plans generated by write-orchestrator-coding-plan.

Usage:
    python evals/check_plan.py path/to/generated-plan.md

The checker intentionally verifies durable, objective planning requirements. Review
repository accuracy and design quality separately with the skill-creator viewer.
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path
from typing import Callable


def contains_all(text: str, terms: tuple[str, ...]) -> bool:
    normalized = re.sub(r"\s+", " ", text.replace("`", "").lower())
    return all(term.lower() in normalized for term in terms)


def has_packet_fields(text: str) -> bool:
    packets = re.findall(r"^### (?:P|S)\d+:.+?(?=^### |\Z)", text, flags=re.MULTILINE | re.DOTALL)
    required = ("owns:", "reads:", "acceptance:", "verification:", "handoff:", "review:")
    return bool(packets) and all(contains_all(packet, required) for packet in packets)


def has_repository_evidence(text: str) -> bool:
    findings = re.search(
        r"^## Repository Findings\s*(.+?)(?=^## |\Z)",
        text,
        flags=re.MULTILINE | re.DOTALL,
    )
    if not findings:
        return False
    return bool(re.search(r"`[^`]+(?:/|\\)[^`]+`", findings.group(1)))


def has_review_assignment(text: str) -> bool:
    section = re.search(
        r"^## Review Assignments\s*(.+?)(?=^## |\Z)",
        text,
        flags=re.MULTILINE | re.DOTALL,
    )
    if not section:
        return False
    reviews = re.findall(
        r"^### R\d+[A-Za-z]*:.+?(?=^### |\Z)",
        section.group(1),
        flags=re.MULTILINE | re.DOTALL,
    )
    required = (
        "target:",
        "timing:",
        "blocks:",
        "consolidation reason:",
        "write policy: inspect-only",
        "return: reviewer_report_v1",
    )
    return bool(reviews) and all(contains_all(review, required) for review in reviews)


def has_review_coverage(text: str) -> bool:
    packet_sections = re.findall(
        r"^### ((?:P|S)\d+):(.+?)(?=^### |\Z)", text, flags=re.MULTILINE | re.DOTALL
    )
    if not packet_sections:
        return False
    assigned_reviews = set(re.findall(r"^### (R\d+[A-Za-z]*):", text, flags=re.MULTILINE))
    referenced_reviews: list[str] = []
    for _, section in packet_sections:
        review = re.search(r"^- review:\s*`?(R\d+[A-Za-z]*)", section, flags=re.MULTILINE)
        if not review:
            return False
        referenced_reviews.append(review.group(1))
    return set(referenced_reviews).issubset(assigned_reviews)


def has_review_graph(text: str) -> bool:
    graph = re.search(
        r"^## Execution Graph\s*(.+?)(?=^## |\Z)", text, flags=re.MULTILINE | re.DOTALL
    )
    if not graph:
        return False
    packet_ids = re.findall(r"^### ((?:P|S)\d+):", text, flags=re.MULTILINE)
    if not packet_ids:
        return False
    review = r"(?:R\d+[A-Za-z]*|\{\s*R\d+[A-Za-z]*(?:\s*\|\|\s*R\d+[A-Za-z]*)+\s*\})"
    return all(
        re.search(rf"\b{re.escape(packet_id)}\b\s*->\s*{review}\s*->\s*(?:GR|G)\d+", graph.group(1))
        for packet_id in packet_ids
    )


BROWSER_TERMS = (
    "browser-qa",
    "browser",
    "screenshot",
    "playwright",
    "click-through",
    "click through",
    "manual check",
    "manually verify",
    "visually verify",
    "visual check",
    "exploratory",
)


def has_automated_only_verification(text: str) -> bool:
    """Packet duties, gates, and schedule must never assign agent-driven browser work."""
    lines = [
        line.lower()
        for line in text.splitlines()
        if re.match(r"^\s*-\s*(test duty|verification|acceptance|test policy|policy|owner):", line.strip(), flags=re.IGNORECASE)
    ]
    schedule = re.search(
        r"^## Test Execution Schedule\s*(.+?)(?=^## |\Z)", text, flags=re.MULTILINE | re.DOTALL
    )
    if schedule:
        lines.extend(
            line.lower() for line in schedule.group(1).splitlines() if line.strip().startswith("-")
        )
    # Strip explicit prohibition clauses ("...; no browser, screenshot...") before scanning.
    scanned = [re.sub(r"\bno\b.*$", "", line) for line in lines]
    return not any(term in line for line in scanned for term in BROWSER_TERMS)


CHECKS: dict[str, tuple[str, Callable[[str], bool]]] = {
    "required_sections": (
        "Contains core plan sections.",
        lambda text: contains_all(
            text,
            (
                "## Runtime Worktree",
                "## Repository Findings",
                "## Execution Graph",
                "## Work Packets",
                "## Review Assignments",
                "## Test Execution Schedule",
                "## Done Criteria",
            ),
        ),
    ),
    "repository_evidence": (
        "Repository Findings cites at least one repository-relative path.",
        has_repository_evidence,
    ),
    "worktree_contract": (
        "Records source branch and HEAD, dedicated worktree, and no automatic merge or cleanup.",
        lambda text: contains_all(
            text,
            ("source:", "head", "dedicated", "worktree", "no merge", "user handles"),
        ),
    ),
    "uncommitted_changes_gate": (
        "Requires a user decision before using relevant source changes absent from HEAD.",
        lambda text: contains_all(
            text,
            ("uncommitted", "untracked", "head", "ask user"),
        ),
    ),
    "execution_graph": (
        "Contains an explicit dependency graph with a gate and dependency arrow.",
        lambda text: "->" in text and bool(re.search(r"\bG\d+\b", text)),
    ),
    "packet_completeness": (
        "Every implementation packet includes ownership, focused reads, acceptance, verification, and handoff.",
        has_packet_fields,
    ),
    "collision_control": (
        "Names ownership and collision rules for shared surfaces.",
        lambda text: contains_all(text, ("## Ownership and Collision Rules", "only")),
    ),
    "review_contract": (
        "Includes timed, blocking inspect-only reviewer assignment with exact target and canonical return contract.",
        has_review_assignment,
    ),
    "review_coverage": (
        "Every implementation packet names a reviewer assignment.",
        has_review_coverage,
    ),
    "review_graph": (
        "Execution graph places packet review and review gate before downstream work.",
        has_review_graph,
    ),
    "communication_contract": (
        "References worker, reviewer, directive, and run-state communication contracts.",
        lambda text: contains_all(
            text,
            (
                "worker_assignment_v1",
                "reviewer_assignment_v1",
                "orchestrator_directive_v1",
                "orchestrator_run_state_v1",
            ),
        ),
    ),
    "automated_only_verification": (
        "Test duties, verification, gates, and schedule assign automated commands only; no agent browser work.",
        has_automated_only_verification,
    ),
    "verification_schedule": (
        "Assigns focused, fan-in, and final verification work.",
        lambda text: contains_all(text, ("T1", "fan-in", "final")),
    ),
}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("plan", type=Path, help="Generated Markdown coding plan to inspect.")
    args = parser.parse_args()

    if not args.plan.is_file():
        parser.error(f"Plan does not exist or is not a file: {args.plan}")

    text = args.plan.read_text(encoding="utf-8")
    results = [
        {"name": name, "text": description, "passed": check(text)}
        for name, (description, check) in CHECKS.items()
    ]
    passed = sum(result["passed"] for result in results)
    print(
        json.dumps(
            {
                "plan": str(args.plan),
                "passed": passed,
                "failed": len(results) - passed,
                "total": len(results),
                "pass_rate": passed / len(results),
                "checks": results,
            },
            indent=2,
        )
    )
    return 0 if passed == len(results) else 1


if __name__ == "__main__":
    sys.exit(main())
